274			"language_rules",
275			"context_rules",
276			"complexity_rules",
277			"modality_rules",
278			"role_bindings",
279			"jailbreak",
280			"pii",
281			"default_model",
282			"reasoning_families",
283			"default_reasoning_effort",
284			"model_config",
285			"vllm_endpoints",
286			"provider_profiles",
287			"strategy",
288			"bert_model",
289		} {
290			if _, ok := raw[key]; ok {
291				t.Fatalf("%s still uses legacy top-level key %q; migrate it to canonical providers/routing/global", rel, key)
292			}
293		}
294	}
