298		path := filepath.Join("..", "..", "..", "..", rel)
299		data, err := os.ReadFile(path)
300		if err != nil {
301			t.Fatalf("failed to read %s: %v", rel, err)
302		}
303		return data
304	}
305	
306	func decodeYAMLMap(t *testing.T, data []byte, rel string) map[string]interface{} {
307		t.Helper()
308		var root map[string]interface{}
309		if err := yamlv3.Unmarshal(data, &root); err != nil {
310			t.Fatalf("failed to decode %s: %v", rel, err)
311		}
312		return root
313	}
314	
315	func mustAssetMapValue(t *testing.T, root map[string]interface{}, key, rel string) map[string]interface{} {
316		t.Helper()
317		value, ok := root[key]
318		if !ok {
319			t.Fatalf("%s is missing %s", rel, key)
320		}
321		typed, ok := value.(map[string]interface{})
322		if !ok {
323			t.Fatalf("%s %s is not a map", rel, key)
324		}
325		return typed
326	}
